import reactor.core.publisher.Flux
import reactor.core.scheduler.Schedulers

class Bad {
    fun process(items: List<String>): Flux<String> {
        return Flux.fromIterable(items)
            .parallel() // bad
            .runOn(Schedulers.parallel())
            .sequential()
    }
}

import reactor.core.publisher.Flux

fun good(items: List<String>): Flux<String> =
    Flux.fromIterable(items).map { it.uppercase() }
